/// One call of the original's box impact (one box): the box's corners and its two matrices (the bone's and its
/// inverse, twelve floats each: the turn's rows, then the place), the line's start and way, what it returned and, for
/// a hit, the point, the normal and the distance it wrote; every value its bits. Recorded from the exe with
/// tools/oracle (random boxes and lines about them; the engine's inverse square root's table set up as the game makes
/// it)
struct ImpactCase
{
	std::array<uint32_t, 3> min;
	std::array<uint32_t, 3> max;
	std::array<uint32_t, 12> matrix;
	std::array<uint32_t, 12> inverse;
	std::array<uint32_t, 3> start;
	std::array<uint32_t, 3> direction;
	bool hit;
	std::array<uint32_t, 3> point;
	std::array<uint32_t, 3> normal;
	uint32_t distance;
};

